CREATE OR REPLACE FUNCTION migration.safe_ratio(p_numerator numeric, p_denominator numeric)
RETURNS TABLE(ratio numeric, error_code text)
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
BEGIN
  -- Try to perform division; on division by zero return the error code as in the T-SQL version.
  RETURN QUERY
    SELECT ROUND(p_numerator / p_denominator, 4)::numeric, NULL::text;
EXCEPTION WHEN division_by_zero THEN
  RETURN QUERY SELECT NULL::numeric, 'DIVISION_BY_ZERO';
END;
$$;

